import hashlib
import math
import pickle

class Counter:
    def __init__(self, p=10):
        self.p = p
        self.m = 1 << p
        self.registers = bytearray(self.m)

    def _hash(self, item):
        h = hashlib.md5(str(item).encode()).digest()
        return int.from_bytes(h[:8], 'big')

    def add(self, item):
        h = self._hash(item)
        idx = h >> (64 - self.p)
        w = h & ((1 << (64 - self.p)) - 1)
        if w == 0:
            rank = 64 - self.p + 1
        else:
            rank = (64 - self.p) - w.bit_length() + 1
        if rank > self.registers[idx]:
            self.registers[idx] = rank

    def count(self):
        m = self.m
        alpha = 0.7213 / (1 + 1.079 / m)
        s = sum(2.0 ** (-r) for r in self.registers)
        e = alpha * m * m / s
        if e <= 2.5 * m:
            v = self.registers.count(0)
            if v > 0:
                e = m * math.log(m / v)
        return int(round(e))

    def __getstate__(self):
        return (self.p, bytes(self.registers))

    def __setstate__(self, state):
        self.p, regs = state
        self.m = 1 << self.p
        self.registers = bytearray(regs)
